// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeKernelIrTestAccess;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Gate C milestone C3: a SPARQL pattern with a variable predicate and a bound endpoint compiles into a kernel, and
 * every combination of variable binding either lowers with the equality filters that make it correct or declines with a
 * stable reason.
 * <p>
 * Correctness is checked against the ordinary evaluator rather than against hand-written expected rows. That is the
 * point: the claim is not "these particular rows come back" but "the compiled path agrees with the interpreter on every
 * shape", and the shapes that must each be explicitly decided include the aliasing cases — predicate equal to object,
 * subject equal to predicate, subject equal to object, and a graph variable that is also the predicate variable — which
 * are exactly where a "fresh variable" branch would overwrite a binding that already exists.
 */
class LmdbNativeVariablePredicateKernelTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final String NS = "http://example.org/";
	private static final IRI S1 = F.createIRI(NS, "s1");
	private static final IRI S2 = F.createIRI(NS, "s2");
	private static final IRI G1 = F.createIRI(NS, "g1");

	/** Enough rows that the compiled tier is worth engaging and the threshold is crossed. */
	private static final int FANOUT = 40;

	private SailRepository repo;

	@AfterEach
	void tearDown() {
		if (repo != null) {
			repo.shutDown();
			repo = null;
		}
		System.clearProperty("rdf4j.lmdb.nativeQueryEngine.enabled");
		System.clearProperty("rdf4j.lmdb.janinoCodegen.enabled");
		System.clearProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		System.clearProperty(
				LmdbNativeKernelIrTestAccess.NODE_PREDICATES_PROPERTY);
		System.clearProperty(LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY);
		System.clearProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY);
	}

	private void open(File dataDir, boolean compiled) {
		if (compiled) {
			System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
			System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
			System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
			System.setProperty(
					LmdbNativeKernelIrTestAccess.NODE_PREDICATES_PROPERTY,
					"true");
			System.setProperty(LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY, "true");
			System.setProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY, "true");
		} else {
			System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
		}
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc,cspo")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore sail = new LmdbStore(dataDir, config);
		repo = new SailRepository(sail);
		repo.init();
		try (RepositoryConnection conn = repo.getConnection()) {
			conn.begin();
			for (int i = 0; i < FANOUT; i++) {
				conn.add(S1, F.createIRI(NS, "p" + i), F.createIRI(NS, "o" + i));
				conn.add(S1, F.createIRI(NS, "p" + i), F.createIRI(NS, "o" + (i + 1)), G1);
				conn.add(S2, F.createIRI(NS, "q" + i), S1);
			}
			// aliasing fodder: a statement whose subject, predicate and object are the same term
			conn.add(S1, F.createIRI(NS, "s1"), S1);
			conn.commit();
		}
		if (compiled) {
			assertThat(AdjacencyEngagementTestAccess.buildNow(sail)).isTrue();
		}
	}

	private List<String> run(String query) {
		List<String> rows = new ArrayList<>();
		try (RepositoryConnection conn = repo.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				StringBuilder row = new StringBuilder();
				for (String name : result.getBindingNames()) {
					row.append(name).append('=').append(bindings.getValue(name)).append('|');
				}
				rows.add(row.toString());
			}
		}
		rows.sort(String::compareTo);
		return rows;
	}

	/**
	 * The binding truth table. Every entry is run twice — once through the ordinary evaluator, once through the
	 * compiled tier — and the two must agree exactly.
	 */
	private static Map<String, String> truthTable() {
		Map<String, String> queries = new LinkedHashMap<>();
		queries.put("fresh-predicate-subject-bound",
				"SELECT ?p ?o WHERE { <" + NS + "s1> ?p ?o }");
		queries.put("fresh-predicate-object-bound",
				"SELECT ?s ?p WHERE { ?s ?p <" + NS + "s1> }");
		queries.put("predicate-bound-upstream",
				"SELECT ?p ?o WHERE { <" + NS + "s2> ?p <" + NS + "s1> . <" + NS + "s1> ?p ?o }");
		queries.put("predicate-equals-object",
				"SELECT ?p WHERE { <" + NS + "s1> ?p ?p }");
		queries.put("subject-equals-predicate",
				"SELECT ?p WHERE { ?p ?p ?o }");
		queries.put("subject-equals-object",
				"SELECT ?p WHERE { ?s ?p ?s }");
		queries.put("graph-variable-is-predicate-variable",
				"SELECT ?p WHERE { GRAPH ?p { <" + NS + "s1> ?p ?o } }");
		queries.put("named-graph-restriction",
				"SELECT ?p ?o WHERE { GRAPH <" + NS + "g1> { <" + NS + "s1> ?p ?o } }");
		queries.put("projected-graph-variable",
				"SELECT ?p ?o ?g WHERE { GRAPH ?g { <" + NS + "s1> ?p ?o } }");
		queries.put("both-endpoints-bound",
				"SELECT ?p WHERE { <" + NS + "s1> ?p <" + NS + "o0> }");
		queries.put("all-unbound",
				"SELECT ?s ?p ?o WHERE { ?s ?p ?o }");
		queries.put("join-through-variable-predicate",
				"SELECT ?p ?o WHERE { <" + NS + "s2> ?q <" + NS + "s1> . <" + NS + "s1> ?p ?o }");
		queries.put("repeated-downstream",
				"SELECT ?p ?o WHERE { <" + NS + "s1> ?p ?o . <" + NS + "s1> ?p ?o }");
		queries.put("count-of-variable-predicate",
				"SELECT (COUNT(*) AS ?c) WHERE { <" + NS + "s1> ?p ?o }");
		queries.put("group-by-variable-predicate",
				"SELECT ?p (COUNT(?o) AS ?c) WHERE { <" + NS + "s1> ?p ?o } GROUP BY ?p");
		return queries;
	}

	@Test
	void theCompiledPathAgreesWithTheOrdinaryEvaluatorOnEveryBindingCombination(@TempDir File interpretedDir,
			@TempDir File compiledDir) {
		Map<String, List<String>> interpreted = new LinkedHashMap<>();
		open(interpretedDir, false);
		try {
			truthTable().forEach((name, query) -> interpreted.put(name, run(query)));
		} finally {
			repo.shutDown();
			repo = null;
		}

		long loweringsBefore = LmdbNativeKernelIrTestAccess
				.variablePredicateLowerings();
		open(compiledDir, true);
		truthTable().forEach((name, query) -> assertThat(run(query)).as("%s", name)
				.containsExactlyElementsOf(interpreted.get(name)));

		assertThat(LmdbNativeKernelIrTestAccess.variablePredicateLowerings())
				.as("at least one variable-predicate pattern must have compiled, or this test proves nothing")
				.isGreaterThan(loweringsBefore);
	}

	/**
	 * With the compiled switch off, the same queries still answer identically — the shape simply runs interpreted. This
	 * is what makes the switch a safe kill switch rather than a behaviour change.
	 */
	@Test
	void turningTheCompiledSwitchOffChangesNothingButTheRoute(@TempDir File onDir, @TempDir File offDir) {
		Map<String, List<String>> on = new LinkedHashMap<>();
		open(onDir, true);
		try {
			truthTable().forEach((name, query) -> on.put(name, run(query)));
		} finally {
			repo.shutDown();
			repo = null;
		}

		System.setProperty(LmdbNativeKernelIrTestAccess.NODE_PREDICATES_PROPERTY,
				"false");
		long loweringsBefore = LmdbNativeKernelIrTestAccess
				.variablePredicateLowerings();
		open(offDir, true);
		System.setProperty(LmdbNativeKernelIrTestAccess.NODE_PREDICATES_PROPERTY,
				"false");
		truthTable().forEach((name, query) -> assertThat(run(query)).as("%s", name)
				.containsExactlyElementsOf(on.get(name)));
		assertThat(LmdbNativeKernelIrTestAccess.variablePredicateLowerings())
				.as("nothing may compile while the switch is off")
				.isEqualTo(loweringsBefore);
	}
}
